using Microsoft.EntityFrameworkCore;using Mbb.Archive.Modules.Retention.Application.Abstractions;using Mbb.Archive.Modules.Retention.Domain.Cases;using Mbb.Archive.Modules.Retention.Domain.Rules;
namespace Mbb.Archive.Modules.Retention.Infrastructure.Persistence;
internal sealed class EfRetentionRepository:IRetentionRepository{private readonly RetentionDbContext _db;public EfRetentionRepository(RetentionDbContext db){_db=db;}public async Task AddRuleAsync(RetentionRule r,CancellationToken ct)=>await _db.Rules.AddAsync(r,ct);public Task<RetentionRule?> GetRuleByCodeAsync(string code,CancellationToken ct)=>_db.Rules.SingleOrDefaultAsync(x=>x.Code==code,ct);public async Task AddCaseAsync(RetentionCase c,CancellationToken ct)=>await _db.Cases.AddAsync(c,ct);public Task<RetentionCase?> GetCaseAsync(Guid id,CancellationToken ct)=>_db.Cases.SingleOrDefaultAsync(x=>x.Id==id,ct);public Task<RetentionCase?> GetCaseByRecordAsync(Guid id,CancellationToken ct)=>_db.Cases.SingleOrDefaultAsync(x=>x.ArchiveRecordId==id,ct);public async Task AddHoldAsync(LegalHold h,CancellationToken ct)=>await _db.Holds.AddAsync(h,ct);public Task<LegalHold?> GetActiveHoldAsync(Guid caseId,CancellationToken ct)=>_db.Holds.SingleOrDefaultAsync(x=>x.RetentionCaseId==caseId&&x.ReleasedAt==null,ct);public async Task<IReadOnlyList<RetentionCase>> GetDueCasesAsync(DateTimeOffset now,int limit,CancellationToken ct)=>await _db.Cases.Where(x=>x.Status==RetentionCaseStatus.Scheduled&&x.DueAt!=null&&x.DueAt<=now&&x.ActiveHoldCount==0).OrderBy(x=>x.DueAt).Take(limit).ToListAsync(ct);}
